      "Earn up to 21% profit bonus when your friends sign up": "احصل على مكافأة ربح تصل إلى 21% عندما يسجل أصدقاؤك",
      "TowerBNB Core Concept": "المفهوم الأساسي لـ TowerBNB",
      "At TowerBNB, the Circulation Yield Protocol (CYP) redefines how digital assets generate value. Built on an IDV-based Circulation strategy model, it offers a highly stable and quantitative trading design. It allows users to earn consistent returns from digital assets, all while eliminating manual monitoring, trading risks, and market volatility through automated and smart-driven interaction methods.": "في TowerBNB، يعيد بروتوكول عائد التداول (CYP) تعريف كيفية توليد الأصول الرقمية للقيمة. استنادًا إلى نموذج استراتيجية التداول القائم على IDV، فإنه يوفر تصميمًا تداوليًا كميًا ومستقرًا للغاية. يتيح للمستخدمين تحقيق عوائد ثابتة من الأصول الرقمية، مع التخلص من المراقبة اليدوية ومخاطر التداول وتقلبات السوق من خلال طرق تفاعل مؤتمتة وذكية.",
      "The TowerBNB Circulation Strategy is operated based on the Ethereum Network and uses Tower’s circular product—Compound-Connected Loop Yield Technology for optimized circulation strategy rewards. Tower’s Circular strategy helps the technology interact with algorithms that automatically maximize returns, allowing participants to earn predictable income from digital assets. The model focuses on high-yield accumulation based on capital-flow efficiency, ensuring maximum potential for both new and existing investors.": "تدار استراتيجية تداول TowerBNB بناءً على شبكة Ethereum وتستخدم منتج Tower الدائري — تكنولوجيا عوائد الحلقة المتصلة المركبة لتحسين مكافآت استراتيجية التداول. تساعد استراتيجية Tower الدائرية التكنولوجيا على التفاعل مع الخوارزميات التي تزيد العوائد تلقائيًا، مما يتيح للمشاركين كسب دخل متوقع من الأصول الرقمية. يركز النموذج على تراكم العوائد العالية بناءً على كفاءة تدفق رأس المال، مما يضمن أقصى إمكانات للمستثمرين الجدد والحاليين.",
      "Join our Telegram channel to stay updated": "انضم إلى قناتنا على Telegram للبقاء على اطلاع",
      "Get the latest updates insights!": "احصل على أحدث التحديثات والرؤى!",
