      "Support": "الدعم",
      "• Sign-up and explore the Free Trial and earn 8 USDT fund.": "• سجل واستكشف التجربة المجانية واكسب رصيد بقيمة 8 USDT.",
      "• Join the group and contact your Manager or Customer Support to receive a 2 USDT joining bonus.": "• انضم إلى المجموعة وتواصل مع مديرك أو دعم العملاء للحصول على مكافأة انضمام بقيمة 2 USDT.",
      "• Claim a total of 10 USDT and use the funds to circulate Tower Upgrade or withdraw upon upgrading to Core 1G Tower Computing.": "• طالب بإجمالي 10 USDT واستخدم الأموال لتداول ترقية البرج أو السحب عند الترقية إلى الحوسبة البرجية Core 1G.",
