      "-Members can only submit one withdrawal application per day.": "- يمكن للأعضاء تقديم طلب سحب واحد فقط يوميًا.",
      "-Minimum Deposit is 50 USDT": "- الحد الأدنى للإيداع هو 50 USDT",
