      "incidental, or consequential damages, including loss of earnings, data, or assets.": "الأضرار العرضية أو التبعية، بما في ذلك خسارة الأرباح، أو البيانات، أو الأصول.",
      "loss due to market fluctuations or external attacks.": "الخسارة بسبب تقلبات السوق أو الهجمات الخارجية.",
      "markets with confidence.": "الأسواق بثقة.",
