      "You must be at least 18 years old and possess the full legal capacity to enter into this agreement.": "Musíte být starší 18 let a mít plnou právní způsobilost k uzavření této smlouvy.",
      "All registration information must be true, accurate, complete, and kept up-to-date.": "Všechny registrační údaje musí být pravdivé, přesné, úplné a neustále aktualizované.",
      "You are prohibited from using the Platform for any illegal activities or those that infringe upon the rights of others.": "Je zakázáno používat platformu pro jakékoli nezákonné aktivity nebo činnosti, které porušují práva ostatních.",
      "TowerBNB provides registered users with services including:": "TowerBNB poskytuje registrovaným uživatelům služby včetně:",
      "Digital asset management, staking functions, and fund circulation (e.g., USDT).": "Správa digitálních aktiv, stakingové funkce a oběh prostředků (např. USDT).",
      "A smartphone Tower mining system (running a computing power package to generate income).": "Systém těžby Tower pro chytré telefony (spuštění balíčku výpočetního výkonu pro generování příjmu).",
      "Team incentive plans (fission income and node ecological incentives).": "Týmové stimulační plány (fúzní příjem a uzlové ekologické pobídky).",
      "Digital asset exchange and withdrawal services.": "Služby směnárny a výběru digitálních aktiv.",
      "TowerBNB reserves the right to adjust the services offered at its discretion.": "TowerBNB si vyhrazuje právo upravit nabízené služby podle svého uvážení.",
      "You are solely responsible for the safekeeping of your account, password, transaction password, and other key information. Any asset loss resulting from your negligence is your responsibility.": "Nesete výhradní odpovědnost za zabezpečení svého účtu, hesla, transakčního hesla a dalších klíčových informací. Jakákoli ztráta majetku v důsledku vaší nedbalosti je vaší odpovědností.",
      "Accounts may not be transferred, rented, loaned, or authorized for use by others.": "Účty nesmí být převáděny, pronajímány, půjčovány ani autorizovány pro použití jinými osobami.",
      "You must immediately notify TowerBNB of any abnormal activity, password leaks, or unauthorized use.": "Musíte okamžitě informovat TowerBNB o jakékoli neobvyklé aktivitě, úniku hesla nebo neoprávněném použití.",
      "The Platform reserves the right to freeze or restrict accounts for security purposes.": "Platforma si vyhrazuje právo zmrazit nebo omezit účty z bezpečnostních důvodů.",
      "You must ensure the correct currency, mainnet type, and address for all deposits, as incorrect operations may result in asset loss for which you are responsible.": "U všech vkladů musíte zajistit správnou měnu, typ mainnetu a adresu, protože nesprávné operace mohou vést ke ztrátě aktiv, za kterou nesete odpovědnost.",
      "Withdrawals require a fund or payment password and must comply with the Platform's limits and fee structures.": "Výběry vyžadují fondové nebo platební heslo a musí splňovat limity a strukturu poplatků platformy.",
      "The Platform may delay processing withdrawals or deposits due to technical maintenance, compliance requirements, or security reviews.": "Platforma může zpozdit zpracování výběrů nebo vkladů z důvodu technické údržby, požadavků na shodu s předpisy nebo bezpečnostních kontrol.",
      "Income is distributed in USDT tokens.": "Příjem je distribuován v tokenech USDT.",
      "TowerBNB does not promise any fixed income.": "TowerBNB neslibuje žádný pevný příjem.",
      "All earnings depend on actual mining operations, market fluctuations, and platform development.": "Veškeré výdělky závisí na skutečných těžebních operacích, tržních výkyvech a vývoji platformy.",
      "The Platform is a technical service provider and does not guarantee user investment decisions or returns.": "Platforma je poskytovatelem technických služeb a nezaručuje investiční rozhodnutí ani výnosy uživatelů.",
      "Users assume sole responsibility for risks associated with participating in digital asset activities.": "Uživatelé přebírají výhradní odpovědnost za rizika spojená s účastí na aktivitách s digitálními aktivy.",
      "TowerBNB is not liable for losses caused by force majeure (natural disasters, hacker attacks, blockchain failures), but will attempt to assist in recovery.": "TowerBNB neodpovídá za ztráty způsobené vyšší mocí (přírodní katastrofy, hackerské útoky, selhání blockchainu), ale pokusí se pomoci při obnově.",
      "Users are strictly forbidden from:": "Uživatelům je přísně zakázáno:",
      "Exploiting vulnerabilities or using scripts to illegally profit.": "Využívat zranitelnosti nebo používat skripty k nezákonnému zisku.",
      "Engaging in illegal financial activities such as money laundering, fraud, or pyramid schemes.": "Zapojovat se do nezákonných finančních aktivit, jako je praní špinavých peněz, podvody nebo pyramidové hry.",
      "Maliciously attacking the system or tampering with data.": "Zlomyslně útočit na systém nebo manipulovat s daty.",
      "Publishing false information or damaging the Platform's reputation.": "Publikovat nepravdivé informace nebo poškozovat pověst platformy.",
      "TowerBNB has the right to suspend or terminate services and pursue legal action against users who engage in these behaviors.": "TowerBNB má právo pozastavit nebo ukončit služby a podniknout právní kroky proti uživatelům, kteří se dopustí tohoto chování.",
      "All Platform content (trademarks, codes, etc.) is protected by law and cannot be used without authorization.": "Veškerý obsah platformy (ochranné známky, kódy atd.) je chráněn zákonem a nesmí být používán bez oprávnění.",
      "TowerBNB reserves the right to update this Agreement at any time. Continued use of the Platform after an update constitutes acceptance of the revised terms.": "TowerBNB si vyhrazuje právo tuto smlouvu kdykoli aktualizovat. Pokračování v používání platformy po aktualizaci znamená přijetí revidovaných podmínek.",
      "TowerBNB Technologies Inc. holds the final right of interpretation of this Agreement.": "Společnost TowerBNB Technologies Inc. si vyhrazuje konečné právo na výklad této smlouvy.",
      "TowerBNB aims to be user-centric, ensuring asset security and promoting access to intelligent computing power. By choosing TowerBNB, you agree to these terms as you embark on a journey of smart mining and asset growth.": "TowerBNB se snaží být zaměřena na uživatele, zajišťovat bezpečnost aktiv a podporovat přístup k inteligentnímu výpočetnímu výkonu. Výběrem TowerBNB souhlasíte s těmito podmínkami a vydáváte se na cestu chytré těžby a růstu aktiv.",
