      " or \"the Platform\"). By registering or using the Platform, you agree to be bound by all the terms herein. If you do not agree, you must not use the Platform’s services.": " ou « la Plateforme »). En vous inscrivant ou en utilisant la Plateforme, vous acceptez d'être lié par toutes les conditions des présentes. Si vous n'acceptez pas, vous ne devez pas utiliser les services de la Plateforme.",
      "You must be at least 18 years old and possess the full legal capacity to enter into this agreement.": "Vous devez être âgé d'au moins 18 ans et posséder la pleine capacité juridique pour conclure cet accord.",
      "All registration information must be true, accurate, complete, and kept up-to-date.": "Toutes les informations d'inscription doivent être vraies, précises, complètes et tenues à jour.",
      "You are prohibited from using the Platform for any illegal activities or those that infringe upon the rights of others.": "Il vous est interdit d'utiliser la Plateforme pour des activités illégales ou qui portent atteinte aux droits d'autrui.",
      "TowerBNB provides registered users with services including:": "TowerBNB fournit aux utilisateurs enregistrés des services comprenant :",
      "Digital asset management, staking functions, and fund circulation (e.g., USDT).": "Gestion d'actifs numériques, fonctions de staking et circulation de fonds (par ex., USDT).",
      "A smartphone Tower mining system (running a computing power package to generate income).": "Un système de minage par tour sur smartphone (exécutant un pack de puissance de calcul pour générer des revenus).",
      "Team incentive plans (fission income and node ecological incentives).": "Plans d'incitation d'équipe (revenus de fission et incitations écologiques de nœud).",
      "Digital asset exchange and withdrawal services.": "Services d'échange et de retrait d'actifs numériques.",
      "TowerBNB reserves the right to adjust the services offered at its discretion.": "TowerBNB se réserve le droit d'ajuster les services offerts à sa discrétion.",
      "You are solely responsible for the safekeeping of your account, password, transaction password, and other key information. Any asset loss resulting from your negligence is your responsibility.": "Vous êtes seul responsable de la sauvegarde de votre compte, mot de passe, mot de passe de transaction et autres informations clés. Toute perte d'actifs résultant de votre négligence est de votre responsabilité.",
      "Accounts may not be transferred, rented, loaned, or authorized for use by others.": "Les comptes ne peuvent être transférés, loués, prêtés ou autorisés à être utilisés par des tiers.",
      "You must immediately notify TowerBNB of any abnormal activity, password leaks, or unauthorized use.": "Vous devez immédiatement informer TowerBNB de toute activité anormale, fuite de mot de passe ou utilisation non autorisée.",
      "The Platform reserves the right to freeze or restrict accounts for security purposes.": "La Plateforme se réserve le droit de geler ou de restreindre les comptes pour des raisons de sécurité.",
      "You must ensure the correct currency, mainnet type, and address for all deposits, as incorrect operations may result in asset loss for which you are responsible.": "Vous devez vous assurer de la devise, du type de réseau principal et de l'adresse corrects pour tous les dépôts, car des opérations incorrectes peuvent entraîner une perte d'actifs dont vous êtes responsable.",
      "Withdrawals require a fund or payment password and must comply with the Platform's limits and fee structures.": "Les retraits nécessitent un mot de passe de fonds ou de paiement et doivent être conformes aux limites et aux structures de frais de la Plateforme.",
      "The Platform may delay processing withdrawals or deposits due to technical maintenance, compliance requirements, or security reviews.": "La Plateforme peut retarder le traitement des retraits ou des dépôts en raison d'une maintenance technique, d'exigences de conformité ou d'examens de sécurité.",
      "Income is distributed in USDT tokens.": "Les revenus sont distribués sous forme de jetons USDT.",
      "TowerBNB does not promise any fixed income.": "TowerBNB ne promet aucun revenu fixe.",
      "All earnings depend on actual mining operations, market fluctuations, and platform development.": "Tous les gains dépendent des opérations de minage réelles, des fluctuations du marché et du développement de la plateforme.",
      "The Platform is a technical service provider and does not guarantee user investment decisions or returns.": "La Plateforme est un fournisseur de services techniques et ne garantit pas les décisions d'investissement ou les rendements des utilisateurs.",
      "Users assume sole responsibility for risks associated with participating in digital asset activities.": "Les utilisateurs assument l'entière responsabilité des risques associés à la participation aux activités d'actifs numériques.",
      "TowerBNB is not liable for losses caused by force majeure (natural disasters, hacker attacks, blockchain failures), but will attempt to assist in recovery.": "TowerBNB n'est pas responsable des pertes causées par la force majeure (catastrophes naturelles, attaques de hackers, pannes de blockchain), mais s'efforcera d'aider à la récupération.",
      "Users are strictly forbidden from:": "Il est strictement interdit aux utilisateurs de :",
      "Exploiting vulnerabilities or using scripts to illegally profit.": "Exploiter des vulnérabilités ou utiliser des scripts pour réaliser des profits illégaux.",
      "Engaging in illegal financial activities such as money laundering, fraud, or pyramid schemes.": "S'engager dans des activités financières illégales telles que le blanchiment d'argent, la fraude ou les systèmes pyramidaux.",
      "Maliciously attacking the system or tampering with data.": "Attaquer malicieusement le système ou altérer les données.",
      "Publishing false information or damaging the Platform's reputation.": "Publier de fausses informations ou nuire à la réputation de la Plateforme.",
      "TowerBNB has the right to suspend or terminate services and pursue legal action against users who engage in these behaviors.": "TowerBNB a le droit de suspendre ou de résilier les services et d'engager des poursuites judiciaires contre les utilisateurs qui se livrent à ces comportements.",
      "All Platform content (trademarks, codes, etc.) is protected by law and cannot be used without authorization.": "Tout le contenu de la Plateforme (marques, codes, etc.) est protégé par la loi et ne peut être utilisé sans autorisation.",
      "TowerBNB reserves the right to update this Agreement at any time. Continued use of the Platform after an update constitutes acceptance of the revised terms.": "TowerBNB se réserve le droit de mettre à jour cet accord à tout temps. L'utilisation continue de la Plateforme après une mise à jour constitue l'acceptation des conditions révisées.",
      "TowerBNB Technologies Inc. holds the final right of interpretation of this Agreement.": "TowerBNB Technologies Inc. détient le droit final d'interprétation de cet accord.",
      "TowerBNB aims to be user-centric, ensuring asset security and promoting access to intelligent computing power. By choosing TowerBNB, you agree to these terms as you embark on a journey of smart mining and asset growth.": "TowerBNB vise à être centrée sur l'utilisateur, à assurer la sécurité des actifs et à promouvoir l'accès à une puissance de calcul intelligente. En choisissant TowerBNB, vous acceptez ces conditions alors que vous vous lancez dans un voyage de minage intelligent et de croissance de vos actifs.",
