      "Earn up to 21% profit bonus when your friends sign up": "Verdienen Sie bis zu 21 % Gewinnbonus, wenn sich Ihre Freunde registrieren",
      "TowerBNB Core Concept": "TowerBNB Kernkonzept",
      "At TowerBNB, the Circulation Yield Protocol (CYP) redefines how digital assets generate value. Built on an IDV-based Circulation strategy model, it offers a highly stable and quantitative trading design. It allows users to earn consistent returns from digital assets, all while eliminating manual monitoring, trading risks, and market volatility through automated and smart-driven interaction methods.": "Bei TowerBNB definiert das Circulation Yield Protocol (CYP) neu, wie digitale Vermögenswerte Wert generieren. Basierend auf einem IDV-gestützten Zirkulationsstrategiemodell bietet es ein hochstabiles und quantitatives Handelsdesign. Es ermöglicht Nutzern, konstante Renditen aus digitalen Vermögenswerten zu erzielen, während manuelles Monitoring, Handelsrisiken und Marktvolatilität durch automatisierte und intelligent gesteuerte Interaktionsmethoden eliminiert werden.",
      "The TowerBNB Circulation Strategy is operated based on the Ethereum Network and uses Tower’s circular product—Compound-Connected Loop Yield Technology for optimized circulation strategy rewards. Tower’s Circular strategy helps the technology interact with algorithms that automatically maximize returns, allowing participants to earn predictable income from digital assets. The model focuses on high-yield accumulation based on capital-flow efficiency, ensuring maximum potential for both new and existing investors.": "Die TowerBNB-Zirkulationsstrategie basiert auf dem Ethereum-Netzwerk und nutzt das zirkuläre Produkt von Tower — die Compound-Connected Loop Yield Technology — für optimierte Zirkulationsstrategie-Belohnungen. Die zirkuläre Strategie von Tower hilft der Technologie, mit Algorithmen zu interagieren, die die Rendite automatisch maximieren, sodass Teilnehmer ein vorhersehbares Einkommen aus digitalen Vermögenswerten erzielen können. Das Modell konzentriert sich auf eine renditestarke Akkumulation basierend auf der Effizienz des Kapitalflusses, um maximales Potenzial für neue und bestehende Investoren zu gewährleisten.",
      "Join our Telegram channel to stay updated": "Treten Sie unserem Telegram-Kanal bei, um auf dem Laufenden zu bleiben",
      "Get the latest updates insights!": "Holen Sie sich die neuesten Updates und Einblicke!",
      "We’re here to help": "Wir sind hier, um zu helfen",
      "Support": "Support",
      "• Sign-up and explore the Free Trial and earn 8 USDT fund.": "• Registrieren Sie sich, testen Sie die kostenlose Testversion und verdienen Sie 8 USDT.",
      "• Join the group and contact your Manager or Customer Support to receive a 2 USDT joining bonus.": "• Treten Sie der Gruppe bei und kontaktieren Sie Ihren Manager oder den Kundensupport, um einen Beitrittsbonus von 2 USDT zu erhalten.",
      "• Claim a total of 10 USDT and use the funds to circulate Tower Upgrade or withdraw upon upgrading to Core 1G Tower Computing.": "• Fordern Sie insgesamt 10 USDT an und nutzen Sie das Guthaben für das Zirkulieren des Tower-Upgrades oder zahlen Sie es aus, sobald Sie auf Core 1G Tower Computing upgraden.",
      "• $2 bonus when activating your account with $50.": "• 2 $ Bonus bei Aktivierung Ihres Kontos mit 50 $.",
      "Create deposit": "Einzahlung erstellen",
