      "Enter your valid Gmail address to receive the verification link to create an account": "Geben Sie Ihre gültige Gmail-Adresse ein, um den Verifizierungslink zur Kontoerstellung zu erhalten",
      "This document outlines the Service Agreement for the use of products and services provided by": "Dieses Dokument beschreibt die Servicevereinbarung für die Nutzung von Produkten und Dienstleistungen von",
      "TowerBNB Technologies Inc.": "TowerBNB Technologies Inc.",
      " (referred to as ": " (bezeichnet als ",
      " or \"the Platform\"). By registering or using the Platform, you agree to be bound by all the terms herein. If you do not agree, you must not use the Platform’s services.": " oder „die Plattform“). Durch die Registrierung oder Nutzung der Plattform erklären Sie sich mit allen hierin enthaltenen Bedingungen einverstanden. Wenn Sie nicht einverstanden sind, dürfen Sie die Dienste der Plattform nicht nutzen.",
      "You must be at least 18 years old and possess the full legal capacity to enter into this agreement.": "Sie müssen mindestens 18 Jahre alt sein und die volle Rechtsfähigkeit besitzen, um diese Vereinbarung einzugehen.",
      "All registration information must be true, accurate, complete, and kept up-to-date.": "Alle Registrierungsinformationen müssen wahrheitsgemäß, genau, vollständig und auf dem neuesten Stand gehalten werden.",
      "You are prohibited from using the Platform for any illegal activities or those that infringe upon the rights of others.": "Es ist Ihnen untersagt, die Plattform für illegale Aktivitäten oder solche, die die Rechte anderer verletzen, zu nutzen.",
      "TowerBNB provides registered users with services including:": "TowerBNB bietet registrierten Nutzern Dienstleistungen einschließlich:",
      "Digital asset management, staking functions, and fund circulation (e.g., USDT).": "Digitale Vermögensverwaltung, Staking-Funktionen und Zirkulation von Geldern (z. B. USDT).",
      "A smartphone Tower mining system (running a computing power package to generate income).": "Ein Smartphone-Tower-Mining-System (Ausführung eines Rechenleistungspakets zur Generierung von Einkommen).",
      "Team incentive plans (fission income and node ecological incentives).": "Teamincentive-Pläne (Fissions-Einkommen und ökologische Knoten-Anreize).",
      "Digital asset exchange and withdrawal services.": "Dienste für den Umtausch und die Auszahlung digitaler Vermögenswerte.",
      "TowerBNB reserves the right to adjust the services offered at its discretion.": "TowerBNB behält sich das Recht vor, die angebotenen Dienste nach eigenem Ermessen anzupassen.",
      "You are solely responsible for the safekeeping of your account, password, transaction password, and other key information. Any asset loss resulting from your negligence is your responsibility.": "Sie sind allein verantwortlich für die sichere Verwahrung Ihres Kontos, Passworts, Transaktionspassworts und anderer wichtiger Informationen. Jeder Vermögensverlust, der durch Ihre Fahrlässigkeit entsteht, liegt in Ihrer Verantwortung.",
      "Accounts may not be transferred, rented, loaned, or authorized for use by others.": "Konten dürfen nicht übertragen, vermietet, verliehen oder von anderen zur Nutzung autorisiert werden.",
      "You must immediately notify TowerBNB of any abnormal activity, password leaks, or unauthorized use.": "Sie müssen TowerBNB unverzüglich über ungewöhnliche Aktivitäten, Passwortlecks oder unbefugte Nutzung informieren.",
      "The Platform reserves the right to freeze or restrict accounts for security purposes.": "Die Plattform behält sich das Recht vor, Konten aus Sicherheitsgründen einzufrieren oder einzuschränken.",
      "You must ensure the correct currency, mainnet type, and address for all deposits, as incorrect operations may result in asset loss for which you are responsible.": "Sie müssen bei allen Einzahlungen die richtige Währung, den richtigen Mainnet-Typ und die richtige Adresse sicherstellen, da fehlerhafte Vorgänge zu Vermögensverlusten führen können, für die Sie verantwortlich sind.",
      "Withdrawals require a fund or payment password and must comply with the Platform's limits and fee structures.": "Auszahlungen erfordern ein Guthaben- oder Zahlungspasswort und müssen den Limits und Gebührenstrukturen der Plattform entsprechen.",
      "The Platform may delay processing withdrawals or deposits due to technical maintenance, compliance requirements, or security reviews.": "Die Plattform kann die Bearbeitung von Aus- oder Einzahlungen aufgrund von technischer Wartung, Compliance-Anforderungen oder Sicherheitsüberprüfungen verzögern.",
      "Income is distributed in USDT tokens.": "Das Einkommen wird in USDT-Token ausgezahlt.",
      "TowerBNB does not promise any fixed income.": "TowerBNB verspricht kein festes Einkommen.",
      "All earnings depend on actual mining operations, market fluctuations, and platform development.": "Alle Einnahmen hängen von den tatsächlichen Mining-Aktivitäten, Marktschwankungen und der Plattformentwicklung ab.",
      "The Platform is a technical service provider and does not guarantee user investment decisions or returns.": "Die Plattform ist ein technischer Dienstleister und übernimmt keine Garantie für Investitionsentscheidungen oder Renditen der Nutzer.",
      "Users assume sole responsibility for risks associated with participating in digital asset activities.": "Nutzer tragen die alleinige Verantwortung für Risiken im Zusammenhang mit der Teilnahme an Aktivitäten mit digitalen Vermögenswerten.",
      "TowerBNB is not liable for losses caused by force majeure (natural disasters, hacker attacks, blockchain failures), but will attempt to assist in recovery.": "TowerBNB haftet nicht für Verluste, die durch höhere Gewalt (Naturkatastrophen, Hackerangriffe, Blockchain-Fehler) verursacht wurden, wird jedoch versuchen, bei der Wiederherstellung zu helfen.",
      "Users are strictly forbidden from:": "Nutzern ist es strengstens untersagt:",
      "Exploiting vulnerabilities or using scripts to illegally profit.": "Schwachstellen auszunutzen oder Skripte zu verwenden, um illegal Gewinn zu erzielen.",
      "Engaging in illegal financial activities such as money laundering, fraud, or pyramid schemes.": "Sich an illegalen Finanzaktivitäten wie Geldwäsche, Betrug oder Schneeballsystemen zu beteiligen.",
      "Maliciously attacking the system or tampering with data.": "Das System böswillig anzugreifen oder Daten zu manipulieren.",
      "Publishing false information or damaging the Platform's reputation.": "Falsche Informationen zu veröffentlichen oder den Ruf der Plattform zu schädigen.",
      "TowerBNB has the right to suspend or terminate services and pursue legal action against users who engage in these behaviors.": "TowerBNB hat das Recht, Dienste auszusetzen oder zu kündigen und rechtliche Schritte gegen Nutzer einzuleiten, die diese Verhaltensweisen zeigen.",
      "All Platform content (trademarks, codes, etc.) is protected by law and cannot be used without authorization.": "Alle Plattforminhalte (Marken, Codes etc.) sind gesetzlich geschützt und dürfen nicht ohne Autorisierung verwendet werden.",
      "TowerBNB reserves the right to update this Agreement at any time. Continued use of the Platform after an update constitutes acceptance of the revised terms.": "TowerBNB behält sich das Recht vor, diese Vereinbarung jederzeit zu aktualisieren. Die fortgesetzte Nutzung der Plattform nach einer Aktualisierung gilt als Annahme der überarbeiteten Bedingungen.",
      "TowerBNB Technologies Inc. holds the final right of interpretation of this Agreement.": "TowerBNB Technologies Inc. behält sich das finale Recht zur Auslegung dieser Vereinbarung vor.",
      "TowerBNB aims to be user-centric, ensuring asset security and promoting access to intelligent computing power. By choosing TowerBNB, you agree to these terms as you embark on a journey of smart mining and asset growth.": "TowerBNB möchte nutzerzentriert sein, die Vermögenssicherheit gewährleisten und den Zugang zu intelligenter Rechenleistung fördern. Mit der Wahl von TowerBNB erklären Sie sich mit diesen Bedingungen einverstanden und beginnen eine Reise des intelligenten Minings und Vermögenswachstums.",
