      "• Join the group and contact your Manager or Customer Support to receive a 2 USDT joining bonus.": "• Csatlakozzon a csoporthoz, és lépjen kapcsolatba menedzserével vagy az ügyfélszolgálattal a 2 USDT csatlakozási bónuszért.",
      "• Claim a total of 10 USDT and use the funds to circulate Tower Upgrade or withdraw upon upgrading to Core 1G Tower Computing.": "• Igényeljen összesen 10 USDT-t, és használja fel az összeget a Tower Upgrade elindítására, vagy vegye fel azt a Core 1G Tower Computingra való frissítés után.",
