      "Earn up to 21% profit bonus when your friends sign up": "Dapatkan bonus keuntungan hingga 21% saat teman Anda mendaftar",
      "TowerBNB Core Concept": "Konsep Inti TowerBNB",
      "At TowerBNB, the Circulation Yield Protocol (CYP) redefines how digital assets generate value. Built on an IDV-based Circulation strategy model, it offers a highly stable and quantitative trading design. It allows users to earn consistent returns from digital assets, all while eliminating manual monitoring, trading risks, and market volatility through automated and smart-driven interaction methods.": "Di TowerBNB, Circulation Yield Protocol (CYP) mendefinisikan ulang cara aset digital menghasilkan nilai. Dibangun di atas model strategi Sirkulasi berbasis IDV, ini menawarkan desain perdagangan kuantitatif yang sangat stabil. Ini memungkinkan pengguna memperoleh pengembalian yang konsisten dari aset digital, sambil menghilangkan pemantauan manual, risiko perdagangan, dan volatilitas pasar melalui metode interaksi otomatis dan cerdas.",
      "The TowerBNB Circulation Strategy is operated based on the Ethereum Network and uses Tower’s circular product—Compound-Connected Loop Yield Technology for optimized circulation strategy rewards. Tower’s Circular strategy helps the technology interact with algorithms that automatically maximize returns, allowing participants to earn predictable income from digital assets. The model focuses on high-yield accumulation based on capital-flow efficiency, ensuring maximum potential for both new and existing investors.": "Strategi Sirkulasi TowerBNB dioperasikan berdasarkan Jaringan Ethereum dan menggunakan produk sirkular Tower—Compound-Connected Loop Yield Technology untuk hadiah strategi sirkulasi yang dioptimalkan. Strategi Sirkulasi Tower membantu teknologi berinteraksi dengan algoritma yang secara otomatis memaksimalkan pengembalian, memungkinkan peserta memperoleh pendapatan yang dapat diprediksi dari aset digital. Model ini berfokus pada akumulasi hasil tinggi berdasarkan efisiensi aliran modal, memastikan potensi maksimum bagi investor baru maupun yang sudah ada.",
      "Join our Telegram channel to stay updated": "Bergabunglah dengan saluran Telegram kami untuk tetap diperbarui",
      "Get the latest updates insights!": "Dapatkan wawasan pembaruan terbaru!",
