      "• Join the group and contact your Manager or Customer Support to receive a 2 USDT joining bonus.": "• Bergabunglah dengan grup dan hubungi Manajer atau Dukungan Pelanggan Anda untuk menerima bonus bergabung sebesar 2 USDT.",
      "• Claim a total of 10 USDT and use the funds to circulate Tower Upgrade or withdraw upon upgrading to Core 1G Tower Computing.": "• Klaim total 10 USDT dan gunakan dana tersebut untuk sirkulasi Peningkatan Tower atau tarik setelah meningkatkan ke Komputasi Tower Core 1G.",
