      "Conclusion": "Kesimpulan",
      "Enter your valid Gmail address to receive the verification link to create an account": "Masukkan alamat Gmail valid Anda untuk menerima tautan verifikasi guna membuat akun",
      "This document outlines the Service Agreement for the use of products and services provided by": "Dokumen ini menguraikan Perjanjian Layanan untuk penggunaan produk dan layanan yang disediakan oleh",
      "TowerBNB Technologies Inc.": "TowerBNB Technologies Inc.",
      " (referred to as ": " (disebut sebagai ",
      " or \"the Platform\"). By registering or using the Platform, you agree to be bound by all the terms herein. If you do not agree, you must not use the Platform’s services.": " atau \"Platform\"). Dengan mendaftar atau menggunakan Platform, Anda setuju untuk terikat oleh semua ketentuan di sini. Jika Anda tidak setuju, Anda tidak boleh menggunakan layanan Platform.",
      "You must be at least 18 years old and possess the full legal capacity to enter into this agreement.": "Anda harus berusia minimal 18 tahun dan memiliki kapasitas hukum penuh untuk memasuki perjanjian ini.",
      "All registration information must be true, accurate, complete, and kept up-to-date.": "Semua informasi registrasi harus benar, akurat, lengkap, dan terus diperbarui.",
      "You are prohibited from using the Platform for any illegal activities or those that infringe upon the rights of others.": "Anda dilarang menggunakan Platform untuk kegiatan ilegal apa pun atau kegiatan yang melanggar hak orang lain.",
      "TowerBNB provides registered users with services including:": "TowerBNB menyediakan layanan kepada pengguna terdaftar termasuk:",
      "Digital asset management, staking functions, and fund circulation (e.g., USDT).": "Manajemen aset digital, fungsi staking, dan sirkulasi dana (misalnya, USDT).",
      "A smartphone Tower mining system (running a computing power package to generate income).": "Sistem penambangan Tower ponsel cerdas (menjalankan paket daya komputasi untuk menghasilkan pendapatan).",
      "Team incentive plans (fission income and node ecological incentives).": "Rencana insentif tim (pendapatan fisi dan insentif ekologis node).",
      "Digital asset exchange and withdrawal services.": "Layanan pertukaran dan penarikan aset digital.",
      "TowerBNB reserves the right to adjust the services offered at its discretion.": "TowerBNB berhak menyesuaikan layanan yang ditawarkan atas kebijakannya sendiri.",
      "You are solely responsible for the safekeeping of your account, password, transaction password, and other key information. Any asset loss resulting from your negligence is your responsibility.": "Anda bertanggung jawab penuh atas penyimpanan akun, kata sandi, kata sandi transaksi, dan informasi kunci lainnya. Kehilangan aset apa pun akibat kelalaian Anda adalah tanggung jawab Anda.",
      "Accounts may not be transferred, rented, loaned, or authorized for use by others.": "Akun tidak boleh dipindahtangankan, disewakan, dipinjamkan, atau diizinkan untuk digunakan oleh orang lain.",
      "You must immediately notify TowerBNB of any abnormal activity, password leaks, or unauthorized use.": "Anda harus segera memberi tahu TowerBNB tentang aktivitas tidak normal, kebocoran kata sandi, atau penggunaan tanpa izin.",
      "The Platform reserves the right to freeze or restrict accounts for security purposes.": "Platform berhak membekukan atau membatasi akun untuk tujuan keamanan.",
      "You must ensure the correct currency, mainnet type, and address for all deposits, as incorrect operations may result in asset loss for which you are responsible.": "Anda harus memastikan mata uang, jenis mainnet, dan alamat yang benar untuk semua setoran, karena operasi yang salah dapat mengakibatkan kehilangan aset yang menjadi tanggung jawab Anda.",
      "Withdrawals require a fund or payment password and must comply with the Platform's limits and fee structures.": "Penarikan memerlukan dana atau kata sandi pembayaran dan harus mematuhi batas dan struktur biaya Platform.",
      "The Platform may delay processing withdrawals or deposits due to technical maintenance, compliance requirements, or security reviews.": "Platform dapat menunda pemrosesan penarikan atau setoran karena pemeliharaan teknis, persyaratan kepatuhan, atau tinjauan keamanan.",
      "Income is distributed in USDT tokens.": "Pendapatan didistribusikan dalam token USDT.",
      "TowerBNB does not promise any fixed income.": "TowerBNB tidak menjanjikan pendapatan tetap.",
      "All earnings depend on actual mining operations, market fluctuations, and platform development.": "Semua penghasilan tergantung pada operasi penambangan aktual, fluktuasi pasar, dan pengembangan platform.",
      "The Platform is a technical service provider and does not guarantee user investment decisions or returns.": "Platform ini adalah penyedia layanan teknis dan tidak menjamin keputusan investasi atau pengembalian pengguna.",
      "Users assume sole responsibility for risks associated with participating in digital asset activities.": "Pengguna menanggung tanggung jawab tunggal atas risiko yang terkait dengan partisipasi dalam aktivitas aset digital.",
      "TowerBNB is not liable for losses caused by force majeure (natural disasters, hacker attacks, blockchain failures), but will attempt to assist in recovery.": "TowerBNB tidak bertanggung jawab atas kerugian yang disebabkan oleh force majeure (bencana alam, serangan peretas, kegagalan blockchain), tetapi akan berusaha membantu pemulihan.",
      "Users are strictly forbidden from:": "Pengguna sangat dilarang dari:",
      "Exploiting vulnerabilities or using scripts to illegally profit.": "Mengeksploitasi kerentanan atau menggunakan skrip untuk meraup untung secara ilegal.",
      "Engaging in illegal financial activities such as money laundering, fraud, or pyramid schemes.": "Terlibat dalam kegiatan keuangan ilegal seperti pencucian uang, penipuan, atau skema piramida.",
      "Maliciously attacking the system or tampering with data.": "Menyerang sistem secara berbahaya atau merusak data.",
      "Publishing false information or damaging the Platform's reputation.": "Menerbitkan informasi palsu atau merusak reputasi Platform.",
      "TowerBNB has the right to suspend or terminate services and pursue legal action against users who engage in these behaviors.": "TowerBNB berhak menangguhkan atau menghentikan layanan dan menuntut jalur hukum terhadap pengguna yang terlibat dalam perilaku ini.",
      "All Platform content (trademarks, codes, etc.) is protected by law and cannot be used without authorization.": "Semua konten Platform (merek dagang, kode, dll.) dilindungi oleh hukum dan tidak dapat digunakan tanpa izin.",
      "TowerBNB reserves the right to update this Agreement at any time. Continued use of the Platform after an update constitutes acceptance of the revised terms.": "TowerBNB berhak memperbarui Perjanjian ini kapan saja. Penggunaan Platform yang berkelanjutan setelah pembaruan merupakan penerimaan atas ketentuan yang direvisi.",
      "TowerBNB Technologies Inc. holds the final right of interpretation of this Agreement.": "TowerBNB Technologies Inc. memegang hak interpretasi akhir dari Perjanjian ini.",
      "TowerBNB aims to be user-centric, ensuring asset security and promoting access to intelligent computing power. By choosing TowerBNB, you agree to these terms as you embark on a journey of smart mining and asset growth.": "TowerBNB bertujuan untuk berpusat pada pengguna, memastikan keamanan aset dan mempromosikan akses ke daya komputasi cerdas. Dengan memilih TowerBNB, Anda menyetujui ketentuan ini saat Anda memulai perjalanan penambangan pintar dan pertumbuhan aset.",
      "- Build your own earning team": "- Bangun tim penghasil Anda sendiri",
