      "-Withdrawals can only be made in multiples of 10 (for example: 10, 20, 30, 40, 50, 100 and so on).*": "- Penarikan hanya dapat dilakukan dalam kelipatan 10 (misalnya: 10, 20, 30, 40, 50, 100 dan seterusnya).*",
