      "• Join the group and contact your Manager or Customer Support to receive a 2 USDT joining bonus.": "• Unisciti al gruppo e contatta il tuo Manager o il Servizio Clienti per ricevere un bonus di iscrizione di 2 USDT.",
      "• Claim a total of 10 USDT and use the funds to circulate Tower Upgrade or withdraw upon upgrading to Core 1G Tower Computing.": "• Riscatta un totale di 10 USDT e usa i fondi per attivare il Tower Upgrade o prelevali dopo aver effettuato l'aggiornamento a Core 1G Tower Computing.",
      "• $2 bonus when activating your account with $50.": "• Bonus di 2 $ quando attivi il tuo account con 50 $.",
