      "Key Provisions of the Agreement": "Disposizioni chiave dell'accordo",
      "User Eligibility and Registration (Article 2):": "Idoneità e registrazione dell'utente (Articolo 2):",
      "Service Offerings (Article 3):": "Offerta di servizi (Articolo 3):",
