      "• Join the group and contact your Manager or Customer Support to receive a 2 USDT joining bonus.": "• به گروه بپیوندید و با مدیر یا پشتیبانی مشتریان تماس بگیرید تا پاداش عضویت ۲ تتر دریافت کنید.",
      "• Claim a total of 10 USDT and use the funds to circulate Tower Upgrade or withdraw upon upgrading to Core 1G Tower Computing.": "• در مجموع ۱۰ تتر دریافت کنید و از این سرمایه برای گردش ارتقای تاور استفاده کنید یا پس از ارتقا به رایانش تاور Core 1G آن را برداشت کنید.",
