      "Digital asset exchange and withdrawal services.": "خدمات تبادل و برداشت دارایی‌های دیجیتال.",
      "TowerBNB reserves the right to adjust the services offered at its discretion.": "TowerBNB حق تغییر یا تنظیم خدمات ارائه شده را بنا به صلاحدید خود محفوظ می‌دارد.",
      "You are solely responsible for the safekeeping of your account, password, transaction password, and other key information. Any asset loss resulting from your negligence is your responsibility.": "مسئولیت حفظ و نگهداری حساب، رمز عبور، رمز تراکنش و سایر اطلاعات کلیدی صرفاً بر عهده شماست. هرگونه از دست رفتن دارایی ناشی از سهل‌انگاری شما بر عهده خودتان خواهد بود.",
      "Accounts may not be transferred, rented, loaned, or authorized for use by others.": "حساب‌ها نباید منتقل شوند، اجاره داده شوند، قرض داده شوند یا برای استفاده دیگران مجاز شوند.",
