      "You must ensure the correct currency, mainnet type, and address for all deposits, as incorrect operations may result in asset loss for which you are responsible.": "شما باید از صحت ارز، نوع شبکه اصلی و آدرس برای تمامی واریزها اطمینان حاصل کنید، زیرا عملیات نادرست ممکن است منجر به از دست رفتن دارایی شود که مسئولیت آن با شماست.",
      "Withdrawals require a fund or payment password and must comply with the Platform's limits and fee structures.": "برداشت‌ها نیاز به رمز سرمایه یا پرداخت دارند و باید با محدودیت‌ها و ساختار کارمزد پلتفرم مطابقت داشته باشند.",
      "The Platform may delay processing withdrawals or deposits due to technical maintenance, compliance requirements, or security reviews.": "پلتفرم ممکن است به دلیل تعمیر و نگهداری فنی، الزامات انطباق یا بررسی‌های امنیتی، پردازش برداشت‌ها یا واریزها را به تاخیر بیندازد.",
      "Income is distributed in USDT tokens.": "درآمدها به صورت توکن‌های تتر (USDT) توزیع می‌شود.",
