      "The Platform is a technical service provider and does not guarantee user investment decisions or returns.": "پلتفرم یک ارائه دهنده خدمات فنی است و تصمیمات سرمایه‌گذاری یا بازدهی کاربران را تضمین نمی‌کند.",
      "Users assume sole responsibility for risks associated with participating in digital asset activities.": "کاربران مسئولیت کامل ریسک‌های مرتبط با مشارکت در فعالیت‌های دارایی دیجیتال را بر عهده می‌گیرند.",
      "TowerBNB is not liable for losses caused by force majeure (natural disasters, hacker attacks, blockchain failures), but will attempt to assist in recovery.": "TowerBNB مسئولیتی در قبال خسارات ناشی از حوادث غیرمترقبه (بلایای طبیعی، حملات هکرها، خرابی‌های بلاکچین) ندارد، اما برای کمک به بازیابی تلاش خواهد کرد.",
      "Users are strictly forbidden from:": "کاربران به شدت از موارد زیر منع شده‌اند:",
