      "• Join the group and contact your Manager or Customer Support to receive a 2 USDT joining bonus.": "• Dołącz do grupy i skontaktuj się ze swoim menedżerem lub obsługą klienta, aby otrzymać 2 USDT bonusu za dołączenie.",
      "• Claim a total of 10 USDT and use the funds to circulate Tower Upgrade or withdraw upon upgrading to Core 1G Tower Computing.": "• Odbierz łącznie 10 USDT i użyj środków na ulepszenie wieży lub wypłać po przejściu na Core 1G Tower Computing.",
