      "You can start your next Circulation Trading session after the Tower cooldown period.": "Możesz rozpocząć kolejną sesję handlu cyrkulacyjnego po okresie schładzania wieży.",
      "This agreement was last updated on": "Niniejsza umowa została ostatnio zaktualizowana dnia",
      "TowerBNB Service Agreement: A Summary": "Umowa o świadczenie usług TowerBNB: Podsumowanie",
      "Key Provisions of the Agreement": "Kluczowe postanowienia umowy",
      "User Eligibility and Registration (Article 2):": "Kwalifikacja i rejestracja użytkownika (Artykuł 2):",
      "Service Offerings (Article 3):": "Oferowane usługi (Artykuł 3):",
