      "Intellectual Property and Agreement Updates (Articles 9 & 10):": "Własność intelektualna i aktualizacje umowy (Artykuły 9 i 10):",
      "Conclusion": "Wnioski",
      "Enter your valid Gmail address to receive the verification link to create an account": "Wprowadź poprawny adres Gmail, aby otrzymać link weryfikacyjny do utworzenia konta",
      "This document outlines the Service Agreement for the use of products and services provided by": "Ten dokument określa Umowę o świadczenie usług w zakresie korzystania z produktów i usług dostarczanych przez",
      "TowerBNB Technologies Inc.": "TowerBNB Technologies Inc.",
      " (referred to as ": " (zwaną dalej ",
      " or \"the Platform\"). By registering or using the Platform, you agree to be bound by all the terms herein. If you do not agree, you must not use the Platform’s services.": " lub \"Platformą\"). Rejestrując się lub korzystając z Platformy, zgadzasz się przestrzegać wszystkich warunków zawartych w niniejszym dokumencie. Jeśli się nie zgadzasz, nie możesz korzystać z usług Platformy.",
      "You must be at least 18 years old and possess the full legal capacity to enter into this agreement.": "Musisz mieć ukończone 18 lat i posiadać pełną zdolność do czynności prawnych, aby zawrzeć tę umowę.",
      "All registration information must be true, accurate, complete, and kept up-to-date.": "Wszystkie informacje rejestracyjne muszą być prawdziwe, dokładne, kompletne i aktualne.",
      "You are prohibited from using the Platform for any illegal activities or those that infringe upon the rights of others.": "Zabrania się korzystania z Platformy do jakichkolwiek nielegalnych działań lub naruszających prawa innych osób.",
      "TowerBNB provides registered users with services including:": "TowerBNB zapewnia zarejestrowanym użytkownikom usługi obejmujące:",
      "Digital asset management, staking functions, and fund circulation (e.g., USDT).": "Zarządzanie aktywami cyfrowymi, funkcje stakingu oraz cyrkulację środków (np. USDT).",
      "A smartphone Tower mining system (running a computing power package to generate income).": "System wydobywczy Tower na smartfony (uruchamianie pakietu mocy obliczeniowej w celu generowania dochodu).",
      "Team incentive plans (fission income and node ecological incentives).": "Plany motywacyjne dla zespołu (dochód z podziału i zachęty ekologiczne węzłów).",
      "Digital asset exchange and withdrawal services.": "Usługi wymiany i wypłaty aktywów cyfrowych.",
      "TowerBNB reserves the right to adjust the services offered at its discretion.": "TowerBNB zastrzega sobie prawo do dostosowania oferowanych usług według własnego uznania.",
      "You are solely responsible for the safekeeping of your account, password, transaction password, and other key information. Any asset loss resulting from your negligence is your responsibility.": "Ponosisz wyłączną odpowiedzialność za bezpieczne przechowywanie swojego konta, hasła, hasła transakcyjnego i innych kluczowych informacji. Wszelkie straty wynikające z Twojego zaniedbania obciążają Ciebie.",
      "Accounts may not be transferred, rented, loaned, or authorized for use by others.": "Konta nie mogą być przekazywane, wynajmowane, wypożyczane ani udostępniane osobom trzecim.",
      "You must immediately notify TowerBNB of any abnormal activity, password leaks, or unauthorized use.": "Musisz niezwłocznie powiadomić TowerBNB o wszelkich nietypowych działaniach, wyciekach haseł lub nieautoryzowanym użyciu.",
      "The Platform reserves the right to freeze or restrict accounts for security purposes.": "Platforma zastrzega sobie prawo do zamrożenia lub ograniczenia kont ze względów bezpieczeństwa.",
      "You must ensure the correct currency, mainnet type, and address for all deposits, as incorrect operations may result in asset loss for which you are responsible.": "Musisz upewnić się co do prawidłowej waluty, typu sieci i adresu dla wszystkich depozytów, ponieważ nieprawidłowe operacje mogą skutkować utratą aktywów.",
      "Withdrawals require a fund or payment password and must comply with the Platform's limits and fee structures.": "Wypłaty wymagają hasła do funduszu lub płatności i muszą być zgodne z limitami oraz strukturą opłat Platformy.",
      "The Platform may delay processing withdrawals or deposits due to technical maintenance, compliance requirements, or security reviews.": "Platforma może opóźnić przetwarzanie wypłat lub depozytów z powodu konserwacji technicznej, wymogów zgodności lub przeglądów bezpieczeństwa.",
      "Income is distributed in USDT tokens.": "Dochód jest wypłacany w tokenach USDT.",
      "TowerBNB does not promise any fixed income.": "TowerBNB nie obiecuje żadnego stałego dochodu.",
      "All earnings depend on actual mining operations, market fluctuations, and platform development.": "Wszystkie zarobki zależą od rzeczywistych operacji wydobywczych, wahań rynkowych i rozwoju platformy.",
      "The Platform is a technical service provider and does not guarantee user investment decisions or returns.": "Platforma jest dostawcą usług technicznych i nie gwarantuje decyzji inwestycyjnych ani zwrotów użytkowników.",
      "Users assume sole responsibility for risks associated with participating in digital asset activities.": "Użytkownicy ponoszą wyłączną odpowiedzialność za ryzyko związane z udziałem w działalności związanej z aktywami cyfrowymi.",
      "TowerBNB is not liable for losses caused by force majeure (natural disasters, hacker attacks, blockchain failures), but will attempt to assist in recovery.": "TowerBNB nie ponosi odpowiedzialności za straty spowodowane siłą wyższą (katastrofy naturalne, ataki hakerskie, awarie blockchain), ale podejmie próby pomocy w odzyskiwaniu środków.",
      "Users are strictly forbidden from:": "Użytkownikom surowo zabrania się:",
      "Exploiting vulnerabilities or using scripts to illegally profit.": "Wykorzystywania luk lub używania skryptów do nielegalnego zarobkowania.",
      "Engaging in illegal financial activities such as money laundering, fraud, or pyramid schemes.": "Angażowania się w nielegalną działalność finansową, taką jak pranie brudnych pieniędzy, oszustwa czy piramidy finansowe.",
      "Maliciously attacking the system or tampering with data.": "Złośliwego atakowania systemu lub manipulowania danymi.",
      "Publishing false information or damaging the Platform's reputation.": "Publikowania fałszywych informacji lub działania na szkodę reputacji Platformy.",
      "TowerBNB has the right to suspend or terminate services and pursue legal action against users who engage in these behaviors.": "TowerBNB ma prawo zawiesić lub zakończyć świadczenie usług oraz podjąć kroki prawne przeciwko użytkownikom dopuszczającym się tych zachowań.",
      "All Platform content (trademarks, codes, etc.) is protected by law and cannot be used without authorization.": "Cała zawartość Platformy (znaki towarowe, kody itp.) jest chroniona prawem i nie może być używana bez upoważnienia.",
      "TowerBNB reserves the right to update this Agreement at any time. Continued use of the Platform after an update constitutes acceptance of the revised terms.": "TowerBNB zastrzega sobie prawo do aktualizacji niniejszej Umowy w dowolnym momencie. Dalsze korzystanie z Platformy po aktualizacji oznacza akceptację zmienionych warunków.",
      "TowerBNB Technologies Inc. holds the final right of interpretation of this Agreement.": "TowerBNB Technologies Inc. zastrzega sobie ostateczne prawo do interpretacji niniejszej Umowy.",
      "TowerBNB aims to be user-centric, ensuring asset security and promoting access to intelligent computing power. By choosing TowerBNB, you agree to these terms as you embark on a journey of smart mining and asset growth.": "TowerBNB dąży do bycia zorientowanym na użytkownika, zapewniając bezpieczeństwo aktywów i promując dostęp do inteligentnej mocy obliczeniowej. Wybierając TowerBNB, zgadzasz się na te warunki.",
      "- Build your own earning team": "- Zbuduj własny zespół zarabiający",
