      "Accounts may not be transferred, rented, loaned, or authorized for use by others.": "As contas não podem ser transferidas, alugadas, emprestadas ou autorizadas para uso por terceiros.",
      "You must immediately notify TowerBNB of any abnormal activity, password leaks, or unauthorized use.": "Você deve notificar imediatamente a TowerBNB sobre qualquer atividade anormal, vazamento de senha ou uso não autorizado.",
      "The Platform reserves the right to freeze or restrict accounts for security purposes.": "A Plataforma reserva-se o direito de congelar ou restringir contas por motivos de segurança.",
      "You must ensure the correct currency, mainnet type, and address for all deposits, as incorrect operations may result in asset loss for which you are responsible.": "Você deve garantir a moeda, o tipo de rede principal e o endereço corretos para todos os depósitos, pois operações incorretas podem resultar em perda de ativos pela qual você é responsável.",
      "Withdrawals require a fund or payment password and must comply with the Platform's limits and fee structures.": "Os saques exigem uma senha de fundo ou pagamento e devem cumprir os limites e estruturas de taxas da Plataforma.",
      "The Platform may delay processing withdrawals or deposits due to technical maintenance, compliance requirements, or security reviews.": "A Plataforma pode atrasar o processamento de saques ou depósitos devido a manutenção técnica, requisitos de conformidade ou análises de segurança.",
      "Income is distributed in USDT tokens.": "A renda é distribuída em tokens USDT.",
      "TowerBNB does not promise any fixed income.": "A TowerBNB não promete nenhuma renda fixa.",
      "All earnings depend on actual mining operations, market fluctuations, and platform development.": "Todos os ganhos dependem das operações reais de mineração, flutuações de mercado e desenvolvimento da plataforma.",
      "The Platform is a technical service provider and does not guarantee user investment decisions or returns.": "A Plataforma é uma provedora de serviços técnicos e não garante as decisões de investimento ou retornos dos usuários.",
      "Users assume sole responsibility for risks associated with participating in digital asset activities.": "Os usuários assumem responsabilidade exclusiva pelos riscos associados à participação em atividades de ativos digitais.",
      "TowerBNB is not liable for losses caused by force majeure (natural disasters, hacker attacks, blockchain failures), but will attempt to assist in recovery.": "A TowerBNB não é responsável por perdas causadas por força maior (desastres naturais, ataques de hackers, falhas de blockchain), mas tentará ajudar na recuperação.",
