      "Maliciously attacking the system or tampering with data.": "Atacar maliciosamente o sistema ou adulterar dados.",
      "Publishing false information or damaging the Platform's reputation.": "Publicar informações falsas ou prejudicar a reputação da Plataforma.",
      "TowerBNB has the right to suspend or terminate services and pursue legal action against users who engage in these behaviors.": "A TowerBNB tem o direito de suspender ou encerrar serviços e buscar medidas legais contra usuários que se envolvam nesses comportamentos.",
      "All Platform content (trademarks, codes, etc.) is protected by law and cannot be used without authorization.": "Todo o conteúdo da Plataforma (marcas registradas, códigos, etc.) é protegido por lei e não pode ser usado sem autorização.",
      "TowerBNB reserves the right to update this Agreement at any time. Continued use of the Platform after an update constitutes acceptance of the revised terms.": "A TowerBNB reserva-se o direito de atualizar este Contrato a qualquer momento. O uso continuado da Plataforma após uma atualização constitui aceitação dos termos revisados.",
      "TowerBNB Technologies Inc. holds the final right of interpretation of this Agreement.": "A TowerBNB Technologies Inc. detém o direito final de interpretação deste Contrato.",
      "TowerBNB aims to be user-centric, ensuring asset security and promoting access to intelligent computing power. By choosing TowerBNB, you agree to these terms as you embark on a journey of smart mining and asset growth.": "A TowerBNB visa ser centrada no usuário, garantindo a segurança dos ativos e promovendo o acesso ao poder de computação inteligente. Ao escolher a TowerBNB, você concorda com estes termos.",
