      "You must be at least 18 years old and possess the full legal capacity to enter into this agreement.": "Вам должно быть не менее 18 лет, и вы должны обладать полной дееспособностью для заключения данного соглашения.",
      "All registration information must be true, accurate, complete, and kept up-to-date.": "Вся регистрационная информация должна быть достоверной, точной, полной и актуальной.",
      "You are prohibited from using the Platform for any illegal activities or those that infringe upon the rights of others.": "Вам запрещено использовать Платформу для любых незаконных действий или действий, нарушающих права других лиц.",
      "TowerBNB provides registered users with services including:": "TowerBNB предоставляет зарегистрированным пользователям услуги, включая:",
      "Digital asset management, staking functions, and fund circulation (e.g., USDT).": "Управление цифровыми активами, функции стейкинга и оборот средств (например, USDT).",
      "A smartphone Tower mining system (running a computing power package to generate income).": "Система майнинга Tower для смартфонов (запуск пакета вычислительной мощности для получения дохода).",
      "Team incentive plans (fission income and node ecological incentives).": "Программы вознаграждения команд (доход от деления сети и экологические стимулы узлов).",
      "Digital asset exchange and withdrawal services.": "Услуги обмена и вывода цифровых активов.",
      "TowerBNB reserves the right to adjust the services offered at its discretion.": "TowerBNB оставляет за собой право изменять предлагаемые услуги по своему усмотрению.",
      "You are solely responsible for the safekeeping of your account, password, transaction password, and other key information. Any asset loss resulting from your negligence is your responsibility.": "Вы несете единоличную ответственность за сохранность вашего аккаунта, паролей и другой ключевой информации.",
      "Accounts may not be transferred, rented, loaned, or authorized for use by others.": "Аккаунты не могут быть переданы, сданы в аренду, одолжены или авторизованы для использования другими лицами.",
      "You must immediately notify TowerBNB of any abnormal activity, password leaks, or unauthorized use.": "Вы должны немедленно уведомить TowerBNB о любой подозрительной активности или утечке паролей.",
      "The Platform reserves the right to freeze or restrict accounts for security purposes.": "Платформа оставляет за собой право замораживать или ограничивать аккаунты в целях безопасности.",
      "You must ensure the correct currency, mainnet type, and address for all deposits, as incorrect operations may result in asset loss for which you are responsible.": "Вы должны обеспечить правильность выбора валюты, типа сети и адреса для всех депозитов во избежание потери активов.",
      "Withdrawals require a fund or payment password and must comply with the Platform's limits and fee structures.": "Вывод средств требует ввода пароля фонда или платежа и должен соответствовать лимитам Платформы.",
      "The Platform may delay processing withdrawals or deposits due to technical maintenance, compliance requirements, or security reviews.": "Платформа может задерживать обработку транзакций по техническим причинам или из-за проверок безопасности.",
      "Income is distributed in USDT tokens.": "Доход распределяется в токенах USDT.",
      "TowerBNB does not promise any fixed income.": "TowerBNB не гарантирует фиксированный доход.",
      "All earnings depend on actual mining operations, market fluctuations, and platform development.": "Все заработки зависят от фактических операций майнинга, рыночных условий и развития платформы.",
      "The Platform is a technical service provider and does not guarantee user investment decisions or returns.": "Платформа является поставщиком технических услуг и не гарантирует результаты инвестиций.",
      "Users assume sole responsibility for risks associated with participating in digital asset activities.": "Пользователи берут на себя единоличную ответственность за риски, связанные с криптоактивностью.",
      "TowerBNB is not liable for losses caused by force majeure (natural disasters, hacker attacks, blockchain failures), but will attempt to assist in recovery.": "TowerBNB не несет ответственности за убытки, вызванные форс-мажорными обстоятельствами, но постарается помочь в восстановлении.",
      "Users are strictly forbidden from:": "Пользователям строго запрещено:",
