      "This document outlines the Service Agreement for the use of products and services provided by": "Tento dokument popisuje Zmluvu o poskytovaní služieb pri používaní produktov a služieb poskytovaných spoločnosťou",
      "TowerBNB Technologies Inc.": "TowerBNB Technologies Inc.",
      " (referred to as ": " (ďalej len ",
      " or \"the Platform\"). By registering or using the Platform, you agree to be bound by all the terms herein. If you do not agree, you must not use the Platform’s services.": " alebo \"Platforma\"). Registráciou alebo používaním Platformy súhlasíte s tým, že budete viazaní všetkými podmienkami. Ak nesúhlasíte, nesmiete služby Platformy používať.",
      "You must be at least 18 years old and possess the full legal capacity to enter into this agreement.": "Musíte mať aspoň 18 rokov a mať plnú právnu spôsobilosť na uzavretie tejto dohody.",
      "All registration information must be true, accurate, complete, and kept up-to-date.": "Všetky registračné informácie musia byť pravdivé, presné, úplné a neustále aktualizované.",
      "You are prohibited from using the Platform for any illegal activities or those that infringe upon the rights of others.": "Máte zakázané používať Platformu na akékoľvek nezákonné aktivity alebo tie, ktoré porušujú práva iných.",
      "TowerBNB provides registered users with services including:": "TowerBNB poskytuje registrovaným používateľom služby vrátane:",
      "Digital asset management, staking functions, and fund circulation (e.g., USDT).": "Správa digitálnych aktív, funkcie stakingu a obeh prostriedkov (napr. USDT).",
      "A smartphone Tower mining system (running a computing power package to generate income).": "Systém ťažby Tower pre smartfóny (spustenie balíka výpočtového výkonu na generovanie príjmu).",
      "Team incentive plans (fission income and node ecological incentives).": "Tímové stimulačné plány (štruktúrovaný príjem a ekologické stimuly uzlov).",
      "Digital asset exchange and withdrawal services.": "Služby zmenárne a výberu digitálnych aktív.",
      "TowerBNB reserves the right to adjust the services offered at its discretion.": "TowerBNB si vyhradzuje právo upraviť ponúkané služby podľa vlastného uváženia.",
      "You are solely responsible for the safekeeping of your account, password, transaction password, and other key information. Any asset loss resulting from your negligence is your responsibility.": "Ste výhradne zodpovední за zabezpečenie svojho účtu, hesla, transakčného hesla a ďalších kľúčových informácií.",
      "Accounts may not be transferred, rented, loaned, or authorized for use by others.": "Účty sa nesmú prevádzať, prenajímať, požičiavať ani autorizovať na používanie inými osobami.",
      "You must immediately notify TowerBNB of any abnormal activity, password leaks, or unauthorized use.": "Musíte okamžite informovať TowerBNB o akejkoľvek neobvyklej aktivite alebo úniku hesla.",
      "The Platform reserves the right to freeze or restrict accounts for security purposes.": "Platforma si vyhradzuje právo zmraziť alebo obmedziť účty z bezpečnostných dôvodov.",
      "You must ensure the correct currency, mainnet type, and address for all deposits, as incorrect operations may result in asset loss for which you are responsible.": "Pri všetkých vkladoch musíte zabezpečiť správnu menu, typ siete a adresu, inak riskujete stratu aktív.",
      "Withdrawals require a fund or payment password and must comply with the Platform's limits and fee structures.": "Výbery vyžadujú heslo fondu alebo platby a musia byť v súlade s limitmi Platformy.",
      "The Platform may delay processing withdrawals or deposits due to technical maintenance, compliance requirements, or security reviews.": "Platforma môže odložiť spracovanie z dôvodu technickej údržby, požiadaviek na zhodu alebo bezpečnostných revízií.",
      "Income is distributed in USDT tokens.": "Príjem je distribuovaný v tokenoch USDT.",
      "TowerBNB does not promise any fixed income.": "TowerBNB nesľubuje žiadny fixný príjem.",
      "All earnings depend on actual mining operations, market fluctuations, and platform development.": "Všetky zárobky závisia od skutočnej ťažby, trhových výkyvov a vývoja platformy.",
      "The Platform is a technical service provider and does not guarantee user investment decisions or returns.": "Platforma je poskytovateľom technických služieb a negarantuje investičné rozhodnutia.",
      "Users assume sole responsibility for risks associated with participating in digital asset activities.": "Používatelia preberajú výhradnú zodpovednosť za riziká spojené s aktivitami s digitálnymi aktívami.",
      "TowerBNB is not liable for losses caused by force majeure (natural disasters, hacker attacks, blockchain failures), but will attempt to assist in recovery.": "TowerBNB nezodpovedá za straty spôsobené vyššou mocou, ale pokúsi sa pomôcť pri obnove.",
      "Users are strictly forbidden from:": "Používateľom je prísne zakázané:",
