      "Earn up to 21% profit bonus when your friends sign up": "Gana hasta un 21% de bonificación de ganancias cuando tus amigos se registren",
      "TowerBNB Core Concept": "Concepto central de TowerBNB",
      "At TowerBNB, the Circulation Yield Protocol (CYP) redefines how digital assets generate value. Built on an IDV-based Circulation strategy model, it offers a highly stable and quantitative trading design. It allows users to earn consistent returns from digital assets, all while eliminating manual monitoring, trading risks, and market volatility through automated and smart-driven interaction methods.": "En TowerBNB, el Protocolo de Rendimiento de Circulación (CYP) redefine cómo los activos digitales generan valor. Basado en un modelo de estrategia de circulación impulsado por IDV, ofrece un diseño de trading cuantitativo y altamente estable. Permite a los usuarios obtener rendimientos consistentes de los activos digitales, al tiempo que elimina el monitoreo manual, los riesgos de trading y la volatilidad del mercado mediante métodos de interacción automatizados e inteligentes.",
      "The TowerBNB Circulation Strategy is operated based on the Ethereum Network and uses Tower’s circular product—Compound-Connected Loop Yield Technology for optimized circulation strategy rewards. Tower’s Circular strategy helps the technology interact with algorithms that automatically maximize returns, allowing participants to earn predictable income from digital assets. The model focuses on high-yield accumulation based on capital-flow efficiency, ensuring maximum potential for both new and existing investors.": "La Estrategia de Circulación de TowerBNB opera en la red Ethereum y utiliza el producto circular de Tower—Tecnología de Rendimiento de Bucle Conectado Compuesto para optimizar las recompensas de la estrategia de circulación. La estrategia circular de Tower ayuda a que la tecnología interactúe con algoritmos que maximizan automáticamente los rendimientos, permitiendo a los participantes obtener ingresos predecibles a partir de activos digitales. El modelo se centra en la acumulación de alto rendimiento basada en la eficiencia del flujo de capital, garantizando el máximo potencial tanto para nuevos inversores como para los ya existentes.",
      "Join our Telegram channel to stay updated": "Únete a nuestro canal de Telegram para mantenerte actualizado",
      "Get the latest updates insights!": "¡Recibe las últimas actualizaciones y novedades!",
      "We’re here to help": "Estamos aquí para ayudarte",
      "Support": "Soporte",
      "• Sign-up and explore the Free Trial and earn 8 USDT fund.": "• Regístrate, explora la prueba gratuita y gana un fondo de 8 USDT.",
      "• Join the group and contact your Manager or Customer Support to receive a 2 USDT joining bonus.": "• Únete al grupo y contacta a tu gerente o al servicio de atención al cliente para recibir un bono de bienvenida de 2 USDT.",
      "• Claim a total of 10 USDT and use the funds to circulate Tower Upgrade or withdraw upon upgrading to Core 1G Tower Computing.": "• Reclama un total de 10 USDT y usa los fondos para circular la actualización de Tower o retíralos al actualizar a Core 1G Tower Computing.",
      "• $2 bonus when activating your account with $50.": "• Bono de $2 al activar tu cuenta con $50.",
