      " or \"the Platform\"). By registering or using the Platform, you agree to be bound by all the terms herein. If you do not agree, you must not use the Platform’s services.": " o \"la Plataforma\"). Al registrarse o utilizar la Plataforma, usted acepta quedar sujeto a todos los términos aquí contenidos. Si no está de acuerdo, no debe utilizar los servicios de la Plataforma.",
      "You must be at least 18 years old and possess the full legal capacity to enter into this agreement.": "Debe tener al menos 18 años de edad y poseer la capacidad legal total para celebrar este acuerdo.",
      "All registration information must be true, accurate, complete, and kept up-to-date.": "Toda la información de registro debe ser verdadera, precisa, completa y mantenerse actualizada.",
      "You are prohibited from using the Platform for any illegal activities or those that infringe upon the rights of others.": "Se le prohíbe utilizar la Plataforma para cualquier actividad ilegal o que infrinja los derechos de terceros.",
      "TowerBNB provides registered users with services including:": "TowerBNB proporciona a los usuarios registrados servicios que incluyen:",
      "Digital asset management, staking functions, and fund circulation (e.g., USDT).": "Gestión de activos digitales, funciones de staking y circulación de fondos (por ejemplo, USDT).",
      "A smartphone Tower mining system (running a computing power package to generate income).": "Un sistema de minería Tower para teléfonos inteligentes (ejecutando un paquete de potencia de cómputo para generar ingresos).",
      "Team incentive plans (fission income and node ecological incentives).": "Planes de incentivos de equipo (ingresos por fisión e incentivos ecológicos de nodos).",
      "Digital asset exchange and withdrawal services.": "Servicios de intercambio y retiro de activos digitales.",
      "TowerBNB reserves the right to adjust the services offered at its discretion.": "TowerBNB se reserva el derecho de ajustar los servicios ofrecidos a su discreción.",
      "You are solely responsible for the safekeeping of your account, password, transaction password, and other key information. Any asset loss resulting from your negligence is your responsibility.": "Usted es el único responsable de la custodia de su cuenta, contraseña, contraseña de transacción y otra información clave. Cualquier pérdida de activos resultante de su negligencia es su responsabilidad.",
      "Accounts may not be transferred, rented, loaned, or authorized for use by others.": "Las cuentas no pueden ser transferidas, alquiladas, prestadas o autorizadas para su uso por terceros.",
      "You must immediately notify TowerBNB of any abnormal activity, password leaks, or unauthorized use.": "Debe notificar inmediatamente a TowerBNB sobre cualquier actividad anormal, filtración de contraseñas o uso no autorizado.",
      "The Platform reserves the right to freeze or restrict accounts for security purposes.": "La Plataforma se reserva el derecho de congelar o restringir cuentas por motivos de seguridad.",
      "You must ensure the correct currency, mainnet type, and address for all deposits, as incorrect operations may result in asset loss for which you are responsible.": "Debe asegurarse de la moneda, el tipo de red principal y la dirección correctos para todos los depósitos, ya que las operaciones incorrectas pueden provocar la pérdida de activos de la que usted será responsable.",
      "Withdrawals require a fund or payment password and must comply with the Platform's limits and fee structures.": "Los retiros requieren una contraseña de fondo o de pago y deben cumplir con los límites y las estructuras de comisiones de la Plataforma.",
      "The Platform may delay processing withdrawals or deposits due to technical maintenance, compliance requirements, or security reviews.": "La Plataforma puede retrasar el procesamiento de retiros o depósitos debido a mantenimiento técnico, requisitos de cumplimiento o revisiones de seguridad.",
      "Income is distributed in USDT tokens.": "Los ingresos se distribuyen en tokens USDT.",
      "TowerBNB does not promise any fixed income.": "TowerBNB no promete ningún ingreso fijo.",
      "All earnings depend on actual mining operations, market fluctuations, and platform development.": "Todas las ganancias dependen de las operaciones reales de minería, las fluctuaciones del mercado y el desarrollo de la plataforma.",
      "The Platform is a technical service provider and does not guarantee user investment decisions or returns.": "La Plataforma es un proveedor de servicios técnicos y no garantiza las decisiones de inversión ni los rendimientos del usuario.",
      "Users assume sole responsibility for risks associated with participating in digital asset activities.": "Los usuarios asumen la responsabilidad exclusiva de los riesgos asociados con la participación en actividades de activos digitales.",
      "TowerBNB is not liable for losses caused by force majeure (natural disasters, hacker attacks, blockchain failures), but will attempt to assist in recovery.": "TowerBNB no es responsable de las pérdidas causadas por fuerza mayor (desastres naturales, ataques de piratas informáticos, fallas de blockchain), pero intentará ayudar en la recuperación.",
      "Users are strictly forbidden from:": "A los usuarios se les prohíbe estrictamente:",
      "Exploiting vulnerabilities or using scripts to illegally profit.": "Explotar vulnerabilidades o utilizar scripts para obtener ganancias de forma ilegal.",
      "Engaging in illegal financial activities such as money laundering, fraud, or pyramid schemes.": "Participar en actividades financieras ilegales como lavado de dinero, fraude o esquemas piramidales.",
      "Maliciously attacking the system or tampering with data.": "Atacar maliciosamente el sistema o alterar los datos.",
      "Publishing false information or damaging the Platform's reputation.": "Publicar información falsa o dañar la reputación de la Plataforma.",
      "TowerBNB has the right to suspend or terminate services and pursue legal action against users who engage in these behaviors.": "TowerBNB tiene el derecho de suspender o rescindir los servicios y emprender acciones legales contra los usuarios que incurran en estos comportamientos.",
      "All Platform content (trademarks, codes, etc.) is protected by law and cannot be used without authorization.": "Todo el contenido de la Plataforma (marcas comerciales, códigos, etc.) está protegido por la ley y no puede ser utilizado sin autorización.",
      "TowerBNB reserves the right to update this Agreement at any time. Continued use of the Platform after an update constitutes acceptance of the revised terms.": "TowerBNB se reserva el derecho de actualizar este Acuerdo en cualquier momento. El uso continuado de la Plataforma después de una actualización constituye la aceptación de los términos revisados.",
      "TowerBNB Technologies Inc. holds the final right of interpretation of this Agreement.": "TowerBNB Technologies Inc. se reserva el derecho final de interpretación de este Acuerdo.",
      "TowerBNB aims to be user-centric, ensuring asset security and promoting access to intelligent computing power. By choosing TowerBNB, you agree to these terms as you embark on a journey of smart mining and asset growth.": "TowerBNB tiene como objetivo centrarse en el usuario, garantizando la seguridad de los activos y promoviendo el acceso a la potencia informática inteligente. Al elegir TowerBNB, usted acepta estos términos a medida que se embarca en un viaje de minería inteligente y crecimiento de activos.",
