      "TowerBNB Core Concept": "TowerBNB Temel Konsepti",
      "At TowerBNB, the Circulation Yield Protocol (CYP) redefines how digital assets generate value. Built on an IDV-based Circulation strategy model, it offers a highly stable and quantitative trading design. It allows users to earn consistent returns from digital assets, all while eliminating manual monitoring, trading risks, and market volatility through automated and smart-driven interaction methods.": "TowerBNB'de, Sirkülasyon Getiri Protokolü (CYP) dijital varlıkların nasıl değer ürettiğini yeniden tanımlar. IDV tabanlı bir Sirkülasyon stratejisi modeli üzerine inşa edilmiş olup, oldukça kararlı ve nicel bir ticaret tasarımı sunar. Kullanıcıların otomatik ve akıllı odaklı etkileşim yöntemleriyle manuel izleme, ticaret riskleri ve piyasa oynaklığını ortadan kaldırırken, dijital varlıklardan tutarlı getiriler elde etmelerini sağlar.",
      "The TowerBNB Circulation Strategy is operated based on the Ethereum Network and uses Tower’s circular product—Compound-Connected Loop Yield Technology for optimized circulation strategy rewards. Tower’s Circular strategy helps the technology interact with algorithms that automatically maximize returns, allowing participants to earn predictable income from digital assets. The model focuses on high-yield accumulation based on capital-flow efficiency, ensuring maximum potential for both new and existing investors.": "TowerBNB Sirkülasyon Stratejisi, Ethereum Ağı temel alınarak işletilir ve optimize edilmiş sirkülasyon stratejisi ödülleri için Tower'ın döngüsel ürünü olan Bileşik Bağlantılı Döngü Getiri Teknolojisini kullanır. Tower'ın Döngüsel stratejisi, teknolojinin getirileri otomatik olarak en üst düzeye çıkaran algoritmalarla etkileşime girmesine yardımcı olarak katılımcıların dijital varlıklardan öngörülebilir gelir elde etmelerini sağlar. Model, hem yeni hem de mevcut yatırımcılar için maksimum potansiyel sağlayarak sermaye akışı verimliliğine dayalı yüksek getirili birikime odaklanır.",
      "Join our Telegram channel to stay updated": "Güncel kalmak için Telegram kanalımıza katılın",
      "Get the latest updates insights!": "En son güncellemeleri ve analizleri alın!",
      "We’re here to help": "Yardım etmek için buradayız",
      "Support": "Destek",
