      "• Join the group and contact your Manager or Customer Support to receive a 2 USDT joining bonus.": "• Gruba katılın ve 2 USDT katılım bonusu almak için Yöneticinizle veya Müşteri Destek ekibiyle iletişime geçin.",
      "• Claim a total of 10 USDT and use the funds to circulate Tower Upgrade or withdraw upon upgrading to Core 1G Tower Computing.": "• Toplam 10 USDT talep edin ve fonları Tower Yükseltmesini sirküle etmek için kullanın veya Core 1G Tower Computing'e yükselttiğinizde çekin.",
