      "Conclusion": "Sonuç",
      "Enter your valid Gmail address to receive the verification link to create an account": "Hesap oluşturmak için doğrulama bağlantısını alabileceğiniz geçerli bir Gmail adresi girin",
      "This document outlines the Service Agreement for the use of products and services provided by": "Bu belge, tarafından sağlanan ürün ve hizmetlerin kullanımına ilişkin Hizmet Sözleşmesini ana hatlarıyla belirtmektedir:",
      "TowerBNB Technologies Inc.": "TowerBNB Technologies Inc.",
      " (referred to as ": " (şu şekilde anılacaktır: ",
      " or \"the Platform\"). By registering or using the Platform, you agree to be bound by all the terms herein. If you do not agree, you must not use the Platform’s services.": " veya \"Platform\"). Platforma kaydolarak veya Platformu kullanarak, buradaki tüm şartlara bağlı kalmayı kabul etmiş sayılırsınız. Kabul etmiyorsanız, Platformun hizmetlerini kullanmamalısınız.",
      "You must be at least 18 years old and possess the full legal capacity to enter into this agreement.": "Bu sözleşmeyi akdetmek için en az 18 yaşında olmanız ve tam hukuki ehliyete sahip olmanız gerekir.",
      "All registration information must be true, accurate, complete, and kept up-to-date.": "Tüm kayıt bilgileri doğru, kesin, eksiksiz olmalı ve güncel tutulmalıdır.",
      "You are prohibited from using the Platform for any illegal activities or those that infringe upon the rights of others.": "Platformu herhangi bir yasa dışı faaliyet veya başkalarının haklarını ihlal eden faaliyetler için kullanmanız yasaktır.",
      "TowerBNB provides registered users with services including:": "TowerBNB, kayıtlı kullanıcılara aşağıdakiler dahil olmak üzere hizmetler sunar:",
      "Digital asset management, staking functions, and fund circulation (e.g., USDT).": "Dijital varlık yönetimi, staking işlevleri ve fon sirkülasyonu (örneğin, USDT).",
      "A smartphone Tower mining system (running a computing power package to generate income).": "Bir akıllı telefon Tower madencilik sistemi (gelir elde etmek için bir işlem gücü paketi çalıştırma).",
      "Team incentive plans (fission income and node ecological incentives).": "Ekip teşvik planları (fisyon geliri ve düğüm ekolojik teşvikleri).",
      "Digital asset exchange and withdrawal services.": "Dijital varlık değişimi ve çekim hizmetleri.",
      "TowerBNB reserves the right to adjust the services offered at its discretion.": "TowerBNB, sunulan hizmetleri kendi takdirine bağlı olarak ayarlama hakkını saklı tutar.",
      "You are solely responsible for the safekeeping of your account, password, transaction password, and other key information. Any asset loss resulting from your negligence is your responsibility.": "Hesabınızın, şifrenizin, işlem şifrenizin ve diğer önemli bilgilerinizin güvenliğinden yalnızca siz sorumlusunuz. İhmalinizden kaynaklanan herhangi bir varlık kaybı sizin sorumluluğunuzdadır.",
      "Accounts may not be transferred, rented, loaned, or authorized for use by others.": "Hesaplar başkalarına devredilemez, kiralanamaz, ödünç verilemez veya başkaları tarafından kullanımına izin verilemez.",
      "You must immediately notify TowerBNB of any abnormal activity, password leaks, or unauthorized use.": "Herhangi bir anormal faaliyet, şifre sızıntısı veya yetkisiz kullanım durumunda TowerBNB'yi derhal bilgilendirmelisiniz.",
      "The Platform reserves the right to freeze or restrict accounts for security purposes.": "Platform, güvenlik amacıyla hesapları dondurma veya kısıtlama hakkını saklı tutar.",
      "You must ensure the correct currency, mainnet type, and address for all deposits, as incorrect operations may result in asset loss for which you are responsible.": "Yanlış işlemler sorumluluğunuzda olan varlık kaybına neden olabileceğinden, tüm yatırımlar için doğru para birimini, ana ağ türünü ve adresini sağladığınızdan emin olmalısınız.",
      "Withdrawals require a fund or payment password and must comply with the Platform's limits and fee structures.": "Çekimler bir fon veya ödeme şifresi gerektirir ve Platformun limitlerine ve ücret yapılarına uygun olmalıdır.",
      "The Platform may delay processing withdrawals or deposits due to technical maintenance, compliance requirements, or security reviews.": "Platform, teknik bakım, uyumluluk gereksinimleri veya güvenlik incelemeleri nedeniyle çekim veya yatırım işlemlerinin işlenmesini geciktirebilir.",
      "Income is distributed in USDT tokens.": "Gelir USDT tokenleri olarak dağıtılır.",
      "TowerBNB does not promise any fixed income.": "TowerBNB herhangi bir sabit gelir vaat etmez.",
      "All earnings depend on actual mining operations, market fluctuations, and platform development.": "Tüm kazançlar gerçek madencilik faaliyetlerine, piyasa dalgalanmalarına ve platform geliştirmelerine bağlıdır.",
      "The Platform is a technical service provider and does not guarantee user investment decisions or returns.": "Platform bir teknik hizmet sağlayıcıdır ve kullanıcının yatırım kararlarını veya getirilerini garanti etmez.",
      "Users assume sole responsibility for risks associated with participating in digital asset activities.": "Kullanıcılar, dijital varlık faaliyetlerine katılmayla ilgili risklerin tek sorumluluğunu üstlenirler.",
      "TowerBNB is not liable for losses caused by force majeure (natural disasters, hacker attacks, blockchain failures), but will attempt to assist in recovery.": "TowerBNB, mücbir sebeplerden (doğal afetler, hacker saldırıları, blockchain arızaları) kaynaklanan kayıplardan sorumlu değildir ancak kurtarmaya yardımcı olmaya çalışacaktır.",
      "Users are strictly forbidden from:": "Kullanıcıların aşağıdakileri yapması kesinlikle yasaktır:",
      "Exploiting vulnerabilities or using scripts to illegally profit.": "Güvenlik açıklarından yararlanmak veya yasa dışı kar elde etmek için komut dosyaları (script) kullanmak.",
      "Engaging in illegal financial activities such as money laundering, fraud, or pyramid schemes.": "Kara para aklama, dolandırıcılık veya piramit şemaları gibi yasa dışı finansal faaliyetlerde bulunmak.",
      "Maliciously attacking the system or tampering with data.": "Sisteme kötü niyetli olarak saldırmak veya verileri tahrif etmek.",
      "Publishing false information or damaging the Platform's reputation.": "Yanlış bilgi yayınlamak veya Platformun itibarına zarar vermek.",
      "TowerBNB has the right to suspend or terminate services and pursue legal action against users who engage in these behaviors.": "TowerBNB, bu davranışlarda bulunan kullanıcıların hizmetlerini askıya alma veya sonlandırma ve haklarında yasal işlem başlatma hakkına sahiptir.",
      "All Platform content (trademarks, codes, etc.) is protected by law and cannot be used without authorization.": "Tüm Platform içeriği (ticari markalar, kodlar vb.) yasalarla korunmaktadır ve izinsiz kullanılamaz.",
      "TowerBNB reserves the right to update this Agreement at any time. Continued use of the Platform after an update constitutes acceptance of the revised terms.": "TowerBNB, bu Sözleşmeyi istediği zaman güncelleme hakkını saklı tutar. Bir güncellemeden sonra Platformun kullanılmaya devam edilmesi, revize edilmiş şartların kabul edildiği anlamına gelir.",
      "TowerBNB Technologies Inc. holds the final right of interpretation of this Agreement.": "TowerBNB Technologies Inc. bu Sözleşmenin nihai yorumlama hakkını saklı tutar.",
      "TowerBNB aims to be user-centric, ensuring asset security and promoting access to intelligent computing power. By choosing TowerBNB, you agree to these terms as you embark on a journey of smart mining and asset growth.": "TowerBNB, varlık güvenliğini sağlayarak ve akıllı işlem gücüne erişimi teşvik ederek kullanıcı odaklı olmayı amaçlamaktadır. TowerBNB'yi seçerek, akıllı madencilik ve varlık büyüme yolculuğuna çıkarken bu şartları kabul etmiş olursınız.",
