      "Abuse of the referral system, including false accounts or self-referrals, will result in forfeiture of rewards and potential account suspension.": "Sahte hesaplar veya kendi kendine referans verme dahil olmak üzere referans sisteminin kötüye kullanılması, ödüllerin kaybedilmesine ve hesabın askıya alınmasına neden olabilir.",
