      "By using HADM GLOBAL, you acknowledge and accept these risks, including the possibility of total asset loss due to market fluctuations or external attacks.": "HADM GLOBAL'ı kullanarak, piyasa dalgalanmaları veya harici saldırılar nedeniyle toplam varlık kaybı olasılığı da dahil olmak üzere bu riskleri kabul etmiş ve onaylamış olursunuz.",
