      "Earn up to 21% profit bonus when your friends sign up": "Do'stlaringiz ro'yxatdan o'tganda 21% gacha foyda bonusi oling",
      "TowerBNB Core Concept": "TowerBNB Asosiy Konsepsiyasi",
      "At TowerBNB, the Circulation Yield Protocol (CYP) redefines how digital assets generate value. Built on an IDV-based Circulation strategy model, it offers a highly stable and quantitative trading design. It allows users to earn consistent returns from digital assets, all while eliminating manual monitoring, trading risks, and market volatility through automated and smart-driven interaction methods.": "TowerBNB platformasida Aylanish Daromad Protokoli (CYP) raqamli aktivlarning qiymat yaratish usulini yangitdan belgilaydi. IDV asosidagi aylanish strategiyasi modeliga qurilgan bo'lib, u yuqori barqaror va miqdoriy (kvantitativ) savdo dizaynini taklif etadi. U foydalanuvchilarga raqamli aktivlardan doimiy daromad olish imkonini beradi va avtomatlashtirilgan hamda aqlli boshqaruv usullari orqali qo'lda nazorat qilish, savdo xavflari va bozor o'zgaruvchanligini bartaraf etadi.",
      "The TowerBNB Circulation Strategy is operated based on the Ethereum Network and uses Tower’s circular product—Compound-Connected Loop Yield Technology for optimized circulation strategy rewards. Tower’s Circular strategy helps the technology interact with algorithms that automatically maximize returns, allowing participants to earn predictable income from digital assets. The model focuses on high-yield accumulation based on capital-flow efficiency, ensuring maximum potential for both new and existing investors.": "TowerBNB Aylanish Strategiyasi Ethereum tarmog'iga asoslangan holda ishlaydi va optimallashtirilgan aylanish strategiyasi mukofotlari uchun Towerning aylanish mahsuloti — Murakkab Bog'langan Siklli Daromad Texnologiyasidan foydalanadi. Towerning aylanish strategiyasi ushbu texnologiyaning daromadni avtomatik ravishda oshiradigan algoritmlar bilan o'zaro ishlashiga yordam beradi, bu esa ishtirokchilarga raqamli aktivlardan oldindan taxmin qilinadigan daromad olish imkonini beradi. Model kapital oqimi samaradorligiga asoslangan yuqori daromadli jamg'arishga qaratilgan bo'lib, yangi va mavjud investorlar uchun maksimal salohiyatni ta'minlaydi.",
      "Join our Telegram channel to stay updated": "Yangiliklardan xabardor bo'lish uchun Telegram kanalimizga qo'shiling",
      "Get the latest updates insights!": "Eng so'nggi yangiliklar va tahlillarni oling!",
      "We’re here to help": "Biz yordam berishga tayyormiz",
      "Support": "Qo'llab-quvvatlash",
      "• Sign-up and explore the Free Trial and earn 8 USDT fund.": "• Ro'yxatdan o'ting va Bepul Sinov muddatini o'rganib, 8 USDT fondiga ega bo'ling.",
      "• Join the group and contact your Manager or Customer Support to receive a 2 USDT joining bonus.": "• Guruhga qo'shiling va 2 USDT qo'shilish bonusini olish uchun menejeringiz yoki mijozlarni qo'llab-quvvatlash xizmati bilan bog'laning.",
      "• Claim a total of 10 USDT and use the funds to circulate Tower Upgrade or withdraw upon upgrading to Core 1G Tower Computing.": "• Jami 10 USDT talep qiling va mablag'larni Tower yangilashda ishlating yoki Core 1G Tower Computing-ga o'tganingizdan so'ng yechib oling.",
      "• $2 bonus when activating your account with $50.": "• Hisobingizni $50 bilan faollashtirganingizda $2 bonus beriladi.",
