      "You are about to start deposit process. The process is fully automated and usually takes about 20 minutes. Make sure to send exact total amount, including fees.": "Siz depozit qo'yish jarayonini boshlash arafasidasiz. Jarayon to'liq avtomatlashtirilgan va odatda 20 daqiqa davom etadi. To'lovlarni hisobga olgan holda aniq umumiy summani yuborganingizga ishonch hosil qiling.",
