      "Minimum Deposit:": "Minimal depozit:",
      "50 USDT. Deposits below 50 USDT are not auto-credited — contact support for manual help.": "50 USDT. 50 USDT dan kam bo'lgan depozitlar avtomatik ravishda hisobga o'tmaydi — qo'lda yordam olish uchun texnik qo'llab-quvvatlashga murojaat qiling.",
      "Quick Deposit Options:": "Tezkor depozit variantlari:",
