      "The withdrawal process is subject to multi-node, confirmation and audit, and the estimated arrival time is 24 to 72 hours.": "Yechib olish jarayoni ko'p tugunli tasdiqlash va auditdan o'tadi va kutilayotgan yetib kelish vaqti 24 dan 72 soatgacha.",
      "Each withdrawal is subject to review, and the next withdrawal can only be performed after the previous withdrawal is completed.": "Har bir yechib olish so'rovi tekshiriladi va keyingi yechib olish faqat oldingi so'rov yakunlangandan keyin amalga oshirilishi mumkin.",
