      "We may update or modify these Terms at any time. Significant changes will be communicated through the app or via email. Your continued use of the Services after such changes indicates your acceptance of the updated Terms.": "Biz ushbu shartlarni istalgan vaqtda yangilashimiz yoki o'zgartirishimiz mumkin. Muhim o'zgarishlar ilova yoki elektron pochta orqali ma'lum qilinadi. Bunday o'zgarishlardan keyin ham xizmatlardan foydalanishni davom ettirishingiz yangilangan shartlarni qabul qilganingizni anglatadi.",
