      "You may not copy, modify, distribute, sell, or lease any part of our platform without prior written permission.": "Oldindan berilgan yozma ruxsatsiz platformamizning biron bir qismini nusxalashingiz, o'zgartirishingiz, tarqatishingiz, sotishingiz yoki ijaraga berishingiz mumkin emas.",
