      "• Claim a total of 10 USDT and use the funds to circulate Tower Upgrade or withdraw upon upgrading to Core 1G Tower Computing.": "• Nhận tổng cộng 10 USDT và sử dụng số tiền này để vận hành Nâng cấp Tower hoặc rút tiền sau khi nâng cấp lên Tính toán Core 1G Tower.",
