      "- Unlimited invite rewards": "- Phần thưởng mời không giới hạn",
      "-All withdrawal requests submitted by members will be subject to an automatic 10% handling fee deduction.": "- Tất cả các yêu cầu rút tiền do thành viên gửi sẽ phải chịu mức khấu trừ tự động 10% phí xử lý.",
      "-Members can only submit one withdrawal application per day.": "- Thành viên chỉ có thể gửi một yêu cầu rút tiền mỗi ngày.",
      "-Minimum Deposit is 50 USDT": "- Số tiền nạp tối thiểu là 50 USDT",
      "-Minimum withdrawal is 10 USDT.": "- Số tiền rút tối thiểu là 10 USDT.",
      "-Please confirm platform deposit address before depositing.": "- Vui lòng xác nhận địa chỉ ví nạp tiền của nền tảng trước khi nạp.",
